'use client';

import { Timer as TimerPrimitive, useTimer, useTimerContext } from '@ark-ui/react/timer';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef, ReactNode } from 'react';
import { Fragment, forwardRef } from 'react';
import styles from './Timer.module.css';

const Timer = forwardRef<
  ComponentRef<typeof TimerPrimitive.Root>,
  ComponentProps<typeof TimerPrimitive.Root>
>(function Timer({ className, ...props }, ref) {
  return (
    <TimerPrimitive.Root
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="timer-root"
    />
  );
});

const TimerRootProvider = forwardRef<
  ComponentRef<typeof TimerPrimitive.RootProvider>,
  ComponentProps<typeof TimerPrimitive.RootProvider>
>(function TimerRootProvider({ className, ...props }, ref) {
  return (
    <TimerPrimitive.RootProvider
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="timer-root-provider"
    />
  );
});

const TimerArea = forwardRef<
  ComponentRef<typeof TimerPrimitive.Area>,
  ComponentProps<typeof TimerPrimitive.Area>
>(function TimerArea({ className, ...props }, ref) {
  return (
    <TimerPrimitive.Area
      ref={ref}
      className={clsx(styles.area, className)}
      {...props}
      data-slot="timer-area"
    />
  );
});

const TimerItem = forwardRef<
  ComponentRef<typeof TimerPrimitive.Item>,
  ComponentProps<typeof TimerPrimitive.Item>
>(function TimerItem({ className, ...props }, ref) {
  return (
    <TimerPrimitive.Item
      ref={ref}
      className={clsx(styles.item, className)}
      {...props}
      data-slot="timer-item"
    />
  );
});

const TimerSeparator = forwardRef<
  ComponentRef<typeof TimerPrimitive.Separator>,
  ComponentProps<typeof TimerPrimitive.Separator>
>(function TimerSeparator({ className, ...props }, ref) {
  return (
    <TimerPrimitive.Separator
      ref={ref}
      className={clsx(styles.separator, className)}
      {...props}
      data-slot="timer-separator"
    />
  );
});

const TimerControl = forwardRef<
  ComponentRef<typeof TimerPrimitive.Control>,
  ComponentProps<typeof TimerPrimitive.Control>
>(function TimerControl({ className, ...props }, ref) {
  return (
    <TimerPrimitive.Control
      ref={ref}
      className={clsx(styles.control, className)}
      {...props}
      data-slot="timer-control"
    />
  );
});

const TimerActionTrigger = forwardRef<
  ComponentRef<typeof TimerPrimitive.ActionTrigger>,
  ComponentProps<typeof TimerPrimitive.ActionTrigger>
>(function TimerActionTrigger({ className, ...props }, ref) {
  return (
    <TimerPrimitive.ActionTrigger
      ref={ref}
      className={clsx(styles.actionTrigger, className)}
      {...props}
      data-slot="timer-action-trigger"
    />
  );
});

type TimerItemType = ComponentProps<typeof TimerPrimitive.Item>['type'];
type TimerSegmentsProps = Omit<
  ComponentProps<typeof TimerPrimitive.Area>,
  'asChild' | 'children'
> & {
  separator?: ReactNode;
  types?: TimerItemType[];
};
type TimerTickDetails = TimerPrimitive.TickDetails;

const defaultTimerSegmentTypes: TimerItemType[] = ['hours', 'minutes', 'seconds'];

const TimerSegments = forwardRef<ComponentRef<typeof TimerPrimitive.Area>, TimerSegmentsProps>(
  function TimerSegments({ separator = ':', types = defaultTimerSegmentTypes, ...props }, ref) {
    return (
      <TimerArea ref={ref} {...props}>
        {types.map((type, index) => (
          <Fragment key={`${type}-${index}`}>
            <TimerItem type={type} />
            {index < types.length - 1 && <TimerSeparator>{separator}</TimerSeparator>}
          </Fragment>
        ))}
      </TimerArea>
    );
  },
);

const TimerContext = TimerPrimitive.Context;

export {
  Timer,
  TimerActionTrigger,
  TimerArea,
  TimerContext,
  TimerControl,
  TimerItem,
  TimerRootProvider,
  TimerSegments,
  TimerSeparator,
  useTimer,
  useTimerContext,
};
export type {
  TimerActionTriggerProps,
  TimerAreaProps,
  TimerContextProps,
  TimerControlProps,
  TimerItemProps,
  TimerRootProps,
  TimerRootProviderProps,
  TimerSeparatorProps,
  UseTimerContext,
  UseTimerProps,
  UseTimerReturn,
} from '@ark-ui/react/timer';
export type { TimerSegmentsProps, TimerTickDetails };

@layer moduix.components {
  .root {
    display: inline-grid;
    place-items: center;
    gap: var(--moduix-spacing-3);
    width: max-content;
    max-inline-size: 100%;
    color: var(--moduix-color-foreground);
  }

  .area {
    display: inline-flex;
    min-inline-size: 0;
    max-inline-size: 100%;
    flex-wrap: wrap;
    align-items: baseline;
    justify-content: center;
    gap: var(--moduix-spacing-1);
    font-size: var(--moduix-text-2xl);
    font-weight: var(--moduix-weight-semibold);
    line-height: var(--moduix-line-height-text-2xl);
    font-variant-numeric: tabular-nums;
  }

  .item {
    min-width: 2ch;
    text-align: center;
  }

  .separator {
    color: var(--moduix-color-muted-foreground);
  }

  .control {
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--moduix-spacing-2);
  }

  .actionTrigger {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--moduix-spacing-2);
    min-height: var(--moduix-size-md);
    margin: 0;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-md);
    padding: var(--moduix-spacing-1-5) var(--moduix-spacing-3);
    background-color: var(--moduix-color-background);
    color: var(--moduix-color-foreground);
    appearance: none;
    font: inherit;
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
    white-space: nowrap;
    cursor: pointer;
    transition: background-color var(--moduix-transition-default);

    @media (hover: hover) {
      &:hover {
        background-color: var(--moduix-color-accent);
      }
    }

    &:focus-visible {
      outline: var(--moduix-focus-ring-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-focus-ring-inset-offset);
    }

    &:disabled {
      opacity: var(--moduix-opacity-disabled);
      cursor: default;
      pointer-events: none;
    }

    &[hidden] {
      display: none;
    }

    & :where(svg) {
      width: var(--moduix-spacing-4);
      height: var(--moduix-spacing-4);
      flex-shrink: 0;
    }
  }
}
